// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        vm.deal(caller, 1 ether);

        address ownerBefore = c.owner();

        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        if (caller != ownerBefore) {
            address ownerAfter = c.owner();
            assertTrue(ownerAfter == ownerBefore);
        } else {
            assertTrue(c.owner() == ownerBefore || c.owner() == newOwner);
        }
    }
}
